def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    regions = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            region = []
            while stack:
                x, y = stack.pop()
                region.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0 and (nx,ny) not in seen:
                        seen.add((nx,ny))
                        stack.append((nx,ny))
            regions.append(region)
    out = [row[:] for row in grid]
    if regions:
        largest = max(regions, key=len)
        smallest = min(regions, key=len)
        for r,c in largest:
            out[r][c] = 8
        for r,c in smallest:
            out[r][c] = 7
    return out

